  "default.project.json": "{\n  \"name\": \"__PROJECT_SLUG__\",\n  \"globIgnorePaths\": [\"**/package.json\", \"**/tsconfig.json\"],\n  \"tree\": {\n    \"$className\": \"DataModel\",\n    \"ReplicatedStorage\": {\n      \"$className\": \"ReplicatedStorage\",\n      \"rbxts_include\": {\n        \"$path\": \"include\",\n        \"node_modules\": {\n          \"$className\": \"Folder\",\n          \"@rbxts\": { \"$path\": \"node_modules/@rbxts\" }\n        }\n      },\n      \"TS\": { \"$path\": \"out/shared\" },\n      \"WorldAssets\": { \"$path\": \"assets/world\" }\n    },\n    \"ServerScriptService\": {\n      \"$className\": \"ServerScriptService\",\n      \"TS\": { \"$path\": \"out/server\" },\n      \"World\": { \"$path\": \"out/world\" },\n      \"Systems\": { \"$path\": \"out/systems\" }\n    },\n    \"StarterPlayer\": {\n      \"$className\": \"StarterPlayer\",\n      \"StarterPlayerScripts\": {\n        \"$className\": \"StarterPlayerScripts\",\n        \"TS\": { \"$path\": \"out/client\" },\n        \"UI\": { \"$path\": \"out/ui\" }\n      }\n    },\n    \"Workspace\": {\n      \"$className\": \"Workspace\",\n      \"$properties\": {\n        \"FilteringEnabled\": true,\n        \"StreamingEnabled\": true,\n        \"StreamingMinRadius\": 128,\n        \"StreamingTargetRadius\": 900\n      }\n    },\n    \"Lighting\": {\n      \"$className\": \"Lighting\",\n      \"$properties\": {\n        \"Technology\": \"Future\",\n        \"ClockTime\": 14,\n        \"Brightness\": 2,\n        \"GlobalShadows\": true\n      }\n    },\n    \"HttpService\": {\n      \"$className\": \"HttpService\",\n      \"$properties\": { \"HttpEnabled\": true }\n    },\n    \"SoundService\": {\n      \"$className\": \"SoundService\",\n      \"$properties\": { \"RespectFilteringEnabled\": true }\n    }\n  }\n}\n",
